import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { renderMarkdown, renderMermaid, TARGETS } from "bitfab-flow";
import { describe, expect, it } from "vitest";
import { renderAmpSkillPack } from "./ampSkillPack.js";
import { setupFlow } from "./setup.js";
import { setupV2Flow } from "./setupV2.js";
const MONOREPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), "../../..");
function generatedAmpSkill(skill) {
    const rendered = renderAmpSkillPack().find((file) => file.skill === skill);
    if (rendered === undefined) {
        throw new Error(`renderAmpSkillPack() emitted no skill named "${skill}"`);
    }
    return rendered.content;
}
function frontmatterField(content, field) {
    return content.match(new RegExp(`^${field}: (.+)$`, "m"))?.[1]?.trim();
}
function modesDocumentedInAmpSkill() {
    return [
        ...generatedAmpSkill("bitfab-setup").matchAll(/^\| `([a-z-]+)` \|/gm),
    ].map((match) => match[1]);
}
const STUDIO_COMMANDS = [
    "clearStudio",
    "closeStudio",
    "openStudio",
    "openTracePlan",
    "startTemplatePreview",
];
describe("setupV2Flow", () => {
    it("preserves every setup mode while using a terminal-native finish state", () => {
        expect(Object.keys(setupV2Flow.entries)).toEqual(Object.keys(setupFlow.entries));
        expect(setupV2Flow.defaultMode).toBe("wizard");
        expect(setupV2Flow.phases.some((phase) => phase.id === "cleanup")).toBe(false);
        expect(setupV2Flow.phases.find((phase) => phase.id === "finish")?.steps).toEqual([expect.objectContaining({ id: "done", next: null })]);
    });
    it("requires generated instrumentation to pass a dedicated verification state", () => {
        const instrumentPhase = setupV2Flow.phases.find((phase) => phase.id === "instrument");
        const writeStep = instrumentPhase?.steps.find((step) => step.id === "write-instrumentation");
        const verifyStep = instrumentPhase?.steps.find((step) => step.id === "verify-instrumentation");
        expect(writeStep).toMatchObject({
            next: "instrument/verify-instrumentation",
        });
        expect(verifyStep).toMatchObject({
            next: "instrument/tell-user-how-to-run",
        });
        expect(verifyStep?.body).toContain("Separately verify the replay script");
        expect(verifyStep?.body).toContain("must not start the application");
        const modifyPhase = setupV2Flow.phases.find((phase) => phase.id === "modify");
        const applyStep = modifyPhase?.steps.find((step) => step.id === "apply-changes");
        const verifyModificationStep = modifyPhase?.steps.find((step) => step.id === "verify-modification");
        expect(applyStep).toMatchObject({
            next: "modify/verify-modification",
        });
        expect(verifyModificationStep).toMatchObject({
            next: "modify/mandatory-stop",
        });
    });
    it("removes Studio-only commands and branches", () => {
        for (const command of STUDIO_COMMANDS) {
            expect(setupV2Flow.commands).not.toHaveProperty(command);
        }
        for (const phase of setupV2Flow.phases) {
            for (const step of phase.steps) {
                for (const command of STUDIO_COMMANDS) {
                    expect(step.commandCalls ?? []).not.toContain(command);
                }
            }
        }
    });
    it("renders a graph whose declared states match the terminal runtime", () => {
        const diagram = renderMermaid(setupV2Flow);
        expect(diagram).toContain("Build, review, and confirm the trace plan inline");
        expect(diagram).toContain("Review and confirm the modified plan inline");
        expect(diagram).toContain("Render the trace plan inline");
        expect(diagram).toContain("Verify the generated instrumentation");
        expect(diagram).toContain("finish_done");
        expect(diagram).not.toMatch(/Studio|browser|preview|cleanup/i);
    });
    it("renders terminal instructions without inherited browser-review choices", () => {
        const instructions = renderMarkdown(setupV2Flow, TARGETS.claude);
        expect(instructions).toContain("Terminal presentation step");
        expect(instructions).not.toContain("View in browser");
        expect(instructions).not.toContain("Open trace plan");
        expect(instructions).not.toContain("Close Studio");
        expect(instructions).not.toContain("confirm later in Studio");
        expect(instructions).toContain("confirm and apply one with `bitfab setup --v2 instrument`");
    });
});
describe("bitfab-amp-plugin skill pack", () => {
    it("is generated from setupV2Flow, so it cannot drift from the flow by hand", () => {
        for (const file of renderAmpSkillPack()) {
            expect(file.content).toContain("Generated by bitfab-plugin-lib/src/flows/ampSkillPack.ts");
        }
    });
    it("documents exactly the modes setupV2Flow defines, in declaration order", () => {
        expect(modesDocumentedInAmpSkill()).toEqual(Object.keys(setupV2Flow.entries));
    });
    it("names the flow's own default mode as the fallback a typo lands on", () => {
        expect(generatedAmpSkill("bitfab-setup")).toContain(`The CLI falls back to \`${setupV2Flow.defaultMode}\``);
    });
    it("gives every skill a frontmatter name matching its directory, which Amp requires", () => {
        const files = renderAmpSkillPack();
        expect(files.length).toBeGreaterThan(0);
        for (const file of files) {
            expect(file.outputPath).toBe(`bitfab-amp-plugin/skills/${file.skill}/SKILL.md`);
            expect(frontmatterField(file.content, "name")).toBe(file.skill);
            expect(frontmatterField(file.content, "description")?.length ?? 0).toBeGreaterThan(40);
        }
    });
    it("matches the committed skill files, so a flow change without a rebuild fails here", () => {
        for (const file of renderAmpSkillPack()) {
            const committed = readFileSync(join(MONOREPO_ROOT, file.outputPath), "utf-8");
            expect(committed).toBe(file.content);
        }
    });
});
